begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
select set_config('request.headers','{"x-peppitness-diary":"free-v1"}',true);
insert into auth.users(id,aud,role,email) values
 ('21111111-1111-4111-8111-111111111111','authenticated','authenticated','free-a@example.invalid'),
 ('21222222-2222-4222-8222-222222222222','authenticated','authenticated','free-b@example.invalid');
select ok(not has_function_privilege('anon','public.start_free_workout_session(uuid,date,text)','execute'),'anonimo senza RPC');
set local role anon;
select throws_ok($q$ select public.start_free_workout_session(gen_random_uuid(),current_date,'Europe/Rome') $q$,'42501',null::text,'anonimo realmente respinto');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"21111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal1"}',true);
select throws_ok($q$ select public.start_free_workout_session(gen_random_uuid(),current_date,'UTC') $q$,'22023','Account time zone changed','fuso account verificato');
select lives_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'avvio senza alcun programma');
select is((select count(*)::int from public.workout_plans),0,'nessun programma fittizio');
select is((select session_kind from public.workout_sessions),'free','tipo persistente');
select ok((select plan_id is null and version_id is null and day_id is null from public.workout_sessions),'nessun riferimento al programma');
select is((select jsonb_array_length(day_snapshot->'exercises') from public.workout_sessions),0,'avvio vuoto');
select lives_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'retry idempotente');
select is((select count(*)::int from public.workout_sessions),1,'nessuna duplicazione');
select set_config('request.headers','{}',true);
select is((select count(*)::int from public.workout_sessions),0,'vecchio client non riceve riferimenti nulli');
select set_config('request.headers','{"x-peppitness-diary":"free-v1"}',true);
select is((select count(*)::int from public.workout_sessions),1,'client aggiornato vede la stessa seduta');
select throws_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date-1,'Europe/Rome') $q$,'PT409','Session id already used','riutilizzo ID con data diversa respinto');
select throws_ok($q$ select public.start_free_workout_session(gen_random_uuid(),current_date,'Europe/Rome') $q$,'PT409','Another session is active','un solo avvio attivo');
select throws_ok($q$ update public.workout_sessions set status='completed',revision=2 $q$,'23514','Free session has no exercises','vuota non completabile');
select throws_ok($q$ update public.workout_sessions set session_kind='program' $q$,'42501',null::text,'tipo non scrivibile direttamente');
select throws_ok($q$ update public.workout_sessions set day_snapshot='{}',revision=2 $q$,'42501',null::text,'snapshot protetto');
select set_config('request.jwt.claims','{"sub":"21222222-2222-4222-8222-222222222222","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.workout_sessions),0,'B non vede A');
select throws_ok($q$ select public.start_workout_session('21ffffff-0000-4000-8000-000000000001',gen_random_uuid(),gen_random_uuid(),current_date,'Europe/Rome') $q$,'42501','Session not available','avvio programma non rivela il tipo di seduta di A');
select throws_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'42501','Session not available','B non ripete avvio A');
select throws_ok($q$ select public.edit_workout_session_exercises(gen_random_uuid(),'21ffffff-0000-4000-8000-000000000001','{"action":"move"}','[]') $q$,'42501','Session not available','B non modifica A');
reset role;
insert into auth.mfa_factors(id,user_id,friendly_name,factor_type,status,created_at,updated_at)
 values('21f00000-0000-4000-8000-000000000001','21111111-1111-4111-8111-111111111111','test','totp','verified',now(),now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"21111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.workout_sessions),0,'MFA protegge lettura');
select throws_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'42501','MFA required','MFA richiesta anche per retry');
select set_config('request.jwt.claims','{"sub":"21111111-1111-4111-8111-111111111111","role":"authenticated","aal":"aal2"}',true);
select lives_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'aal2 ammessa');
delete from public.workout_sessions where id='21ffffff-0000-4000-8000-000000000001';
select is((select count(*)::int from public.workout_sessions),0,'annullamento vuota consentito');
select throws_ok($q$ select public.start_free_workout_session('21ffffff-0000-4000-8000-000000000001',current_date,'Europe/Rome') $q$,'PT409','Free session discarded','retry dopo eliminazione non ricrea la seduta');
reset role;
select ok(not has_table_privilege('authenticated','peppitness_private.free_workout_starts','select,insert,update,delete'),'ricevute di avvio private');
select * from finish();
rollback;
